        int operacion = 0;
        int inicio = 0;
        int cantidad = 0;
        int valor = 0;

        if (!(std::cin >> operacion >> inicio >> cantidad >> valor)) {
            return 1;
        }
        int procesados = -3;
        if (operacion == 1) {
            procesados = aplicar(datos, inicio, cantidad, valor);
        } else if (operacion == 2) {
            procesados = llenar(nullptr, cantidad, valor);
        }
        std::string estado = "Cambio";
        if (procesados == 0) {
            estado = "Vacio";
        } else if (procesados == -1) {
            estado = "Rechazo";
